mapper.select:
SELECT r.*, e.name as employee_name, e.employee_no, CASE WHEN d.unit_type = 2 THEN d.unit_name WHEN p1.unit_type = 2 THEN p1.unit_name WHEN p2.unit_type = 2 THEN p2.unit_name WHEN p3.unit_type = 2 THEN p3.unit_name ELSE NULL END as company_name, d.unit_name as dept_name, s.shift_name, (SELECT COALESCE(SUM(a.duration), 0) FROM hr_application a WHERE a.employee_id = r.employee_id AND a.app_type = 'overtime' AND a.status = 1 AND DATE(a.start_time) <= r.att_date AND DATE(a.end_time) >= r.att_date) as overtime_duration, (SELECT COALESCE(SUM(a.duration), 0) FROM hr_application a WHERE a.employee_id = r.employee_id AND a.app_type = 'business' AND a.status = 1 AND DATE(a.start_time) <= r.att_date AND DATE(a.end_time) >= r.att_date) as business_duration, (SELECT COALESCE(SUM(a.duration), 0) FROM hr_application a WHERE a.employee_id = r.employee_id AND a.app_type = 'leave' AND a.title = '1' AND a.status = 1 AND DATE(a.start_time) <= r.att_date AND DATE(a.end_time) >= r.att_date) as annual_leave_duration, (SELECT COALESCE(SUM(a.duration), 0) FROM hr_application a WHERE a.employee_id = r.employee_id AND a.app_type = 'leave' AND a.title = '2' AND a.status = 1 AND DATE(a.start_time) <= r.att_date AND DATE(a.end_time) >= r.att_date) as personal_leave_duration, (SELECT COALESCE(SUM(a.duration), 0) FROM hr_application a WHERE a.employee_id = r.employee_id AND a.app_type = 'leave' AND a.title = '3' AND a.status = 1 AND DATE(a.start_time) <= r.att_date AND DATE(a.end_time) >= r.att_date) as sick_leave_duration, (SELECT COALESCE(SUM(a.duration), 0) FROM hr_application a WHERE a.employee_id = r.employee_id AND a.app_type = 'leave' AND a.title = '4' AND a.status = 1 AND DATE(a.start_time) <= r.att_date AND DATE(a.end_time) >= r.att_date) as marriage_leave_duration, (SELECT COALESCE(SUM(a.duration), 0) FROM hr_application a WHERE a.employee_id = r.employee_id AND a.app_type = 'leave' AND a.title = '5' AND a.status = 1 AND DATE(a.start_time) <= r.att_date AND DATE(a.end_time) >= r.att_date) as maternity_leave_duration, (SELECT COALESCE(SUM(a.duration), 0) FROM hr_application a WHERE a.employee_id = r.employee_id AND a.app_type = 'leave' AND a.title = '6' AND a.status = 1 AND DATE(a.start_time) <= r.att_date AND DATE(a.end_time) >= r.att_date) as paternity_leave_duration, (SELECT COALESCE(SUM(a.duration), 0) FROM hr_application a WHERE a.employee_id = r.employee_id AND a.app_type = 'leave' AND a.title = '7' AND a.status = 1 AND DATE(a.start_time) <= r.att_date AND DATE(a.end_time) >= r.att_date) as bereavement_leave_duration FROM att_daily_record r LEFT JOIN hr_employee e ON r.employee_id = e.id LEFT JOIN org_unit d ON e.dept_id = d.id AND d.deleted = 0 LEFT JOIN org_unit p1 ON d.parent_id = p1.id AND p1.deleted = 0 LEFT JOIN org_unit p2 ON p1.parent_id = p2.id AND p2.deleted = 0 LEFT JOIN org_unit p3 ON p2.parent_id = p3.id AND p3.deleted = 0 LEFT JOIN att_shift s ON r.shift_id = s.id
AND r.att_date >= #{startDate}
AND r.att_date <= #{endDate}
AND e.dept_id IN
#{orgId}
AND e.employee_no LIKE CONCAT('%', #{employeeNo}, '%')
AND e.name LIKE CONCAT('%', #{employeeName}, '%')
AND r.status = #{status}
ORDER BY r.att_date DESC, e.employee_no, r.period_id

SELECT r.*, e.name as employee_name, e.employee_no, CASE WHEN d.unit_type = 2 THEN d.unit_name WHEN p1.unit_type = 2 THEN p1.unit_name WHEN p2.unit_type = 2 THEN p2.unit_name WHEN p3.unit_type = 2 THEN p3.unit_name ELSE NULL END as company_name, d.unit_name as dept_name, s.shift_name, (SELECT COALESCE(SUM(a.duration), 0) FROM hr_application a WHERE a.employee_id = r.employee_id AND a.app_type = 'overtime' AND a.status = 1 AND DATE(a.start_time) <= r.att_date AND DATE(a.end_time) >= r.att_date) as overtime_duration, (SELECT COALESCE(SUM(a.duration), 0) FROM hr_application a WHERE a.employee_id = r.employee_id AND a.app_type = 'business' AND a.status = 1 AND DATE(a.start_time) <= r.att_date AND DATE(a.end_time) >= r.att_date) as business_duration, (SELECT COALESCE(SUM(a.duration), 0) FROM hr_application a WHERE a.employee_id = r.employee_id AND a.app_type = 'leave' AND a.title = '1' AND a.status = 1 AND DATE(a.start_time) <= r.att_date AND DATE(a.end_time) >= r.att_date) as annual_leave_duration, (SELECT COALESCE(SUM(a.duration), 0) FROM hr_application a WHERE a.employee_id = r.employee_id AND a.app_type = 'leave' AND a.title = '2' AND a.status = 1 AND DATE(a.start_time) <= r.att_date AND DATE(a.end_time) >= r.att_date) as personal_leave_duration, (SELECT COALESCE(SUM(a.duration), 0) FROM hr_application a WHERE a.employee_id = r.employee_id AND a.app_type = 'leave' AND a.title = '3' AND a.status = 1 AND DATE(a.start_time) <= r.att_date AND DATE(a.end_time) >= r.att_date) as sick_leave_duration, (SELECT COALESCE(SUM(a.duration), 0) FROM hr_application a WHERE a.employee_id = r.employee_id AND a.app_type = 'leave' AND a.title = '4' AND a.status = 1 AND DATE(a.start_time) <= r.att_date AND DATE(a.end_time) >= r.att_date) as marriage_leave_duration, (SELECT COALESCE(SUM(a.duration), 0) FROM hr_application a WHERE a.employee_id = r.employee_id AND a.app_type = 'leave' AND a.title = '5' AND a.status = 1 AND DATE(a.start_time) <= r.att_date AND DATE(a.end_time) >= r.att_date) as maternity_leave_duration, (SELECT COALESCE(SUM(a.duration), 0) FROM hr_application a WHERE a.employee_id = r.employee_id AND a.app_type = 'leave' AND a.title = '6' AND a.status = 1 AND DATE(a.start_time) <= r.att_date AND DATE(a.end_time) >= r.att_date) as paternity_leave_duration, (SELECT COALESCE(SUM(a.duration), 0) FROM hr_application a WHERE a.employee_id = r.employee_id AND a.app_type = 'leave' AND a.title = '7' AND a.status = 1 AND DATE(a.start_time) <= r.att_date AND DATE(a.end_time) >= r.att_date) as bereavement_leave_duration FROM att_daily_record r LEFT JOIN hr_employee e ON r.employee_id = e.id LEFT JOIN org_unit d ON e.dept_id = d.id AND d.deleted = 0 LEFT JOIN org_unit p1 ON d.parent_id = p1.id AND p1.deleted = 0 LEFT JOIN org_unit p2 ON p1.parent_id = p2.id AND p2.deleted = 0 LEFT JOIN org_unit p3 ON p2.parent_id = p3.id AND p3.deleted = 0 LEFT JOIN att_shift s ON r.shift_id = s.id
AND r.att_date >= #{startDate}
AND r.att_date <= #{endDate}
AND e.dept_id IN
#{orgId}
AND e.employee_no LIKE CONCAT('%', #{employeeNo}, '%')
AND e.name LIKE CONCAT('%', #{employeeName}, '%')
AND r.status = #{status}
ORDER BY r.att_date DESC, e.employee_no, r.period_id
